import { useState } from 'react';
import type { FormEvent } from 'react';
import {
  JxStepper,
  JxInputField,
  JxSelect,
  JxTextareaField,
  JxButton,
  JxDivider,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  comment: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void | Promise<void>;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  comment: '',
};

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);
  const [showErrors, setShowErrors] = useState(false);
  const [sending, setSending] = useState(false);
  const [sendError, setSendError] = useState<string | null>(null);

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) => {
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const contactErrors = {
    name: data.name.trim() ? undefined : 'Укажите имя',
    email: /^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(data.email.trim())
      ? undefined
      : 'Укажите адрес вида name@example.com',
  };

  const addressErrors = {
    country: data.country ? undefined : 'Выберите страну',
    city: data.city.trim() ? undefined : 'Укажите город',
    street: data.street.trim() ? undefined : 'Укажите улицу и дом',
  };

  const stepErrors = step === 0 ? contactErrors : step === 1 ? addressErrors : {};
  const stepValid = Object.values(stepErrors).every((error) => error === undefined);

  const countryLabel = countries.find((item) => item.value === data.country)?.label ?? '—';

  const goBack = () => {
    setShowErrors(false);
    setSendError(null);
    setStep((current) => Math.max(0, current - 1));
  };

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!stepValid) {
      setShowErrors(true);
      return;
    }
    if (step < steps.length - 1) {
      setShowErrors(false);
      setStep((current) => current + 1);
      return;
    }
    setSending(true);
    setSendError(null);
    try {
      await onSubmit(data);
    } catch {
      setSendError('Не удалось отправить данные. Попробуйте ещё раз.');
    } finally {
      setSending(false);
    }
  };

  const errorText = (key: keyof RegistrationData) =>
    showErrors ? (stepErrors as Partial<Record<keyof RegistrationData, string>>)[key] : undefined;

  return (
    <form onSubmit={submit} noValidate style={{ display: 'grid', gap: '24px', maxWidth: '560px' }}>
      <JxStepper steps={steps} current={step} />

      <div style={{ display: 'grid', gap: '16px' }}>
        {step === 0 && (
          <>
            <JxInputField
              label="Имя и фамилия"
              required
              autoComplete="name"
              value={data.name}
              onChange={(event) => set('name', event.target.value)}
              errorText={errorText('name')}
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              autoComplete="email"
              value={data.email}
              onChange={(event) => set('email', event.target.value)}
              errorText={errorText('email')}
              helperText="На этот адрес придёт подтверждение"
            />
            <JxInputField
              label="Телефон"
              type="tel"
              prefix="+7"
              autoComplete="tel"
              placeholder="900 000-00-00"
              value={data.phone}
              onChange={(event) => set('phone', event.target.value)}
              helperText="Необязательно"
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxSelect
              label="Страна"
              placeholder="Выберите страну"
              options={countries}
              value={data.country}
              onValueChange={(value) => set('country', value)}
            />
            {showErrors && addressErrors.country && (
              <JxAlert intent="danger" title="Страна не выбрана">
                {addressErrors.country}
              </JxAlert>
            )}
            <JxInputField
              label="Город"
              required
              autoComplete="address-level2"
              value={data.city}
              onChange={(event) => set('city', event.target.value)}
              errorText={errorText('city')}
            />
            <JxInputField
              label="Улица и дом"
              required
              autoComplete="street-address"
              value={data.street}
              onChange={(event) => set('street', event.target.value)}
              errorText={errorText('street')}
            />
            <JxTextareaField
              label="Комментарий для курьера"
              rows={3}
              maxLength={300}
              value={data.comment}
              onChange={(event) => set('comment', event.target.value)}
              helperText={`${data.comment.length}/300`}
            />
          </>
        )}

        {step === 2 && (
          <>
            <JxDivider label="Контакты" />
            <dl style={{ display: 'grid', gap: '8px', margin: 0 }}>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
                <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.name}</dd>
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
                <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.email}</dd>
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Телефон</dt>
                <dd style={{ margin: 0, textAlign: 'right' }}>{data.phone ? `+7 ${data.phone}` : '—'}</dd>
              </div>
              <JxDivider label="Адрес" />
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Страна</dt>
                <dd style={{ margin: 0, textAlign: 'right' }}>{countryLabel}</dd>
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
                <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.city}</dd>
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Адрес</dt>
                <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.street}</dd>
              </div>
              {data.comment && (
                <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                  <dt style={{ color: 'var(--jx-text-2)' }}>Комментарий</dt>
                  <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.comment}</dd>
                </div>
              )}
            </dl>
            {sendError && (
              <JxAlert intent="danger" title="Ошибка отправки">
                {sendError}
              </JxAlert>
            )}
          </>
        )}
      </div>

      <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0 || sending} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={sending}>
          {step === steps.length - 1 ? (sending ? 'Отправляем…' : 'Отправить') : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

export default RegistrationWizard;

